-- Event-complete ordinary scenarios. Data only; the shared story builder owns
-- placeholder binding, discovery gating, carrier validation and placement.
local M={}

local function triplet(question,event,outcome,unresolved,readings,organisation,grounding,claim,response,review,comparisons,optional)
 return {question=question,event=event,outcome=outcome,unresolved=unresolved,readings=readings,
  organisation=organisation,grounding=grounding,essential={"claim","response","review"},
  anchors={claim=claim,response=response,review=review},comparisons=comparisons,optional=optional or {}}
end
local function links(a,b,c)
 return {
  {requires={"claim","response"},from="response",to="claim",kind="recontextualises",text=a},
  {requires={"response","review"},from="review",to="response",kind="recontextualises",text=b},
  {requires={"claim","response","review"},from="review",to="claim",kind="recontextualises",text=c}
 }
end

local scenarios={
 ["transfer-nobody-arranged"]={
  [1]=triplet("Who authorised the transfer?","McCoy Logging Co. reassigned a mechanic to its mill after a truck breakdown.","The mechanic reported to the mill under a documented emergency reassignment.","The records do not explain why the ordinary approval form was skipped.",{"An emergency reassignment kept a working mill supplied.","The paperwork records the move but not the missing approval."},"McCoy Logging Co.","McCoyLoggingCorp",
   {kind="dispatch",title="Emergency transfer / {CODE}",observation="A carbon transfer sheet with a grease thumbprint beside the destination box.",source="McCOY LOGGING CO.\n{DATE1}\n{P1} released for mill repair crew after haul truck failure.\nRetained copy and approval enquiries: {B}.\nApproval form to follow when the truck does.",note="This sheet releases {P1} for an urgent mill repair and directs approval enquiries to {B}. A stopped mill affects every crew waiting on it."},
   {kind="notebook",title="Mill maintenance log / {CODE}",observation="A maintenance log open to a page where a belt change is entered in block capitals.",source="{DATE2}\nMill line stopped 06:15. {P1} fitted replacement belt; line running 08:05.\nForeman note: keep mechanic; truck can wait its turn.",note="The mill log records {P1} doing the repair and the line running again. It records no approving name."},
   {kind="receipt",title="Payroll transfer entry / {CODE}",observation="A narrow payroll entry with the new work site stamped in purple.",source="{DATE3}\n{P1} charged to mill repair crew from {DATE2}. Emergency transfer entered after work completed.\nApproval field blank. Payroll accepts a working belt as supporting paperwork.",note="Payroll put {P1} on the mill crew after the repair. The blank approval still has its own little job: remaining blank."},
   links("The maintenance log identifies the emergency work named on the transfer sheet.","Payroll records the reassignment after the repair was completed.","The transfer had a recorded purpose and result: the mill repair was done and {P1} was reassigned, though no approval is recorded.")),
  [2]=triplet("Why was a storage clerk moved to another site?","U-Store It moved a clerk to inventory storm-damaged units.","The clerk completed the inventory shift and returned to the original roster.","The records do not identify who first reported the damage.",{"The move was a short practical response to damaged storage units.","The paperwork settles the shift while leaving the original report unnamed."},"U-Store It","UStoreItMuldraugh",
   {kind="dispatch",title="Temporary assignment / {CODE}",observation="A thin assignment slip with rain spots along its top edge.",source="U-STORE IT\n{DATE1}\nAssign {P1} to inventory storm-damaged units.\nRetained copy and tenant enquiries: {B}.\nReturn when the damaged-unit list is signed. Do not promise tenants a time.",note="This assignment puts {P1} on damaged-unit inventory and gives tenants {B} for enquiries. Their possessions remain in place while the list decides what happened."},
   {kind="notebook",title="Unit inventory log / {CODE}",observation="A squared notebook page listing unit numbers and damp cartons.",source="{DATE2}\n{P1} inventoried eight affected units. Three locks replaced; contents left in place for owners.\nList signed and forwarded to retained copy address {B}.",note="The inventory log records eight affected units, replacement locks, and the signed list forwarded to {B}."},
   {kind="receipt",title="Roster correction / {CODE}",observation="A roster strip where a single shift is crossed out and re-entered.",source="{DATE3}\nTemporary assignment {CODE} closed. {P1} returned to regular roster.\nDamage report source: not retained. Shift sheet forwarded to {B} for filing.",note="The roster closes the temporary move and forwards its shift sheet to {B}. It names no source for the damage report."},
   links("The inventory log records the work the assignment ordered.","The roster correction closes the assignment after the signed inventory returned.","The transfer was a completed temporary inventory shift, not an unexplained disappearance; the first damage report remains unnamed."))
