  [2]=triplet("Did the motel receive the linen delivery?","Sunstar Motel accepted emergency linen through a night clerk while the listed manager was away.","The linen was counted into the motel store room and the delivery was charged to the motel.","The documents do not establish why the manager’s name was used at the door.",{"The linen reached the motel and was accepted by its night clerk.","The receipt name is inaccurate, even though the delivery itself is documented."},"Sunstar Motel","SunstarMotel",
   {kind="dispatch",title="Linen docket / {CODE}",observation="A delivery docket folded through its signature box.",source="SUNSTAR MOTEL\n{DATE1}\nEmergency linen delivered to motel stock. Received by: {P2}.\nRetained copy and charge enquiry: {B}.\nDriver note: manager's name supplied at desk; rooms needed sheets before check-in.",note="The docket names {P2} and points to {B} for its retained copy. The driver records what the desk gave him, while guests wait for rooms to be made up."},
